const updateWorkspacesLastPulledAt = `-- name: UpdateWorkspacesLastPulledAt :exec
; -- @no-track
UPDATE workspace SET last_pulled_at = ?1 WHERE id IN (/*SLICE:workspace_ids*/?)
`

type UpdateWorkspacesLastPulledAtParams struct {
	LastPulledAt sql.NullTime `json:"last_pulled_at"`
	WorkspaceIds []string     `json:"workspace_ids"`
}

func (q *Queries) UpdateWorkspacesLastPulledAt(ctx context.Context, arg UpdateWorkspacesLastPulledAtParams) error {
	query := updateWorkspacesLastPulledAt
	var queryParams []interface{}
	queryParams = append(queryParams, arg.LastPulledAt)
	if len(arg.WorkspaceIds) > 0 {
		for _, v := range arg.WorkspaceIds {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:workspace_ids*/?", strings.Repeat(",?", len(arg.WorkspaceIds))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:workspace_ids*/?", "NULL", 1)
	}
	_, err := q.db.ExecContext(ctx, query, queryParams...)
	return err
}

